declare
  v_kind text;
  v_id text;
  v_uuid uuid;
begin
  if p_topic is null or p_topic = '' then
    return false;
  end if;
  v_kind := split_part(p_topic, ':', 1);
  v_id := split_part(p_topic, ':', 2);
  if v_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return false;
  end if;
  v_uuid := v_id::uuid;

  if v_kind in ('safety-alerts', 'remote-session-family') then
    return private.is_family_member(v_uuid);
  end if;

  if v_kind in ('remote-session', 'webrtc-signals') then
    return exists (
      select 1
      from public.remote_sessions s
      where s.id = v_uuid
        and (s.child_user_id = auth.uid() or private.is_family_parent(s.family_id))
    );
  end if;

  return false;
end;

declare
  v_device public.devices;
  v_result jsonb;
begin
  select * into v_device
  from public.devices
  where id = p_device_id
  for update;
  if not found then
    raise exception 'device_not_found' using errcode = 'P0002';
  end if;

  if p_actor_user_id is null or not exists (
    select 1 from public.family_members
    where family_id = v_device.family_id
      and user_id = p_actor_user_id
      and role = 'parent'
      and status = 'active'
  ) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  v_result := private.unlink_child(
    v_device.family_id,
    v_device.child_user_id,
    p_actor_user_id
  );

  perform private.record_audit(
    v_device.family_id,
    p_actor_user_id,
    v_device.id,
    'device_recovery_started',
    'device',
    v_device.id::text,
    jsonb_build_object(
      'child_user_id', v_device.child_user_id,
      'devices_revoked', v_result ->> 'devices_revoked',
      'already_unlinked', coalesce((v_result ->> 'already_removed')::boolean, false)
    )
  );

  return v_result || jsonb_build_object(
    'recovery', 'started',
    'old_device_id', v_device.id
  );
end;

declare
  v_device public.devices;
  v_session public.remote_sessions;
begin
  if p_kind is null or p_kind not in ('audio', 'video') then
    raise exception 'invalid_kind';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_device_id::text, 0));

  select * into v_device
  from public.devices
  where id = p_device_id;

  if not found then
    raise exception 'device_not_found';
  end if;
  if v_device.status <> 'active' then
    raise exception 'device_not_active';
  end if;

  update public.remote_sessions
  set status = 'expired',
      ended_at = now(),
      ended_reason = 'expired'
  where device_id = p_device_id
    and status = 'requested'
    and expires_at is not null
    and expires_at <= now();

  if exists (
    select 1
    from public.remote_sessions
    where device_id = p_device_id
      and status in ('requested', 'accepted', 'active')
  ) then
    raise exception 'session_in_progress' using errcode = 'P0001';
  end if;

  insert into public.remote_sessions (
    family_id,
    device_id,
    parent_user_id,
    child_user_id,
    kind,
    status,
    requested_at,
    expires_at,
    consent_recorded
  )
  values (
    v_device.family_id,
    v_device.id,
    p_parent_user_id,
    v_device.child_user_id,
    p_kind,
    'requested',
    now(),
    now() + interval '10 minutes',
    false
  )
  returning * into v_session;

  return v_session;
end;

declare
  v_membership public.family_members;
  v_devices integer := 0;
  v_sessions integer := 0;
begin
  if p_actor_user_id is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_actor_user_id <> p_child_user_id then
    if not exists (
      select 1 from public.family_members
      where family_id = p_family_id
        and user_id = p_actor_user_id
        and role = 'parent'
        and status = 'active'
    ) then
      raise exception 'forbidden' using errcode = '42501';
    end if;
  end if;

  select * into v_membership
  from public.family_members
  where family_id = p_family_id
    and user_id = p_child_user_id
    and role = 'child'
  for update;
  if not found then
    raise exception 'membership_not_found' using errcode = 'P0002';
  end if;
  if v_membership.status = 'removed' then
    return jsonb_build_object(
      'status', 'unlinked',
      'family_id', p_family_id,
      'child_user_id', p_child_user_id,
      'already_removed', true,
      'devices_revoked', 0,
      'sessions_ended', 0
    );
  end if;

  update public.family_members
  set status = 'removed', removed_at = now()
  where id = v_membership.id;

  update public.devices
  set status = 'revoked',
      secret_hash = null,
      credential_revoked_at = now()
  where family_id = p_family_id
    and child_user_id = p_child_user_id
    and status <> 'revoked';
  get diagnostics v_devices = row_count;

  update public.remote_sessions
  set status = 'ended',
      ended_at = now(),
      ended_by = p_actor_user_id,
      ended_reason = coalesce(ended_reason, 'member_unlinked')
  where family_id = p_family_id
    and child_user_id = p_child_user_id
    and status in ('requested', 'accepted', 'active');
  get diagnostics v_sessions = row_count;

  update public.device_pairing_tokens
  set status = 'revoked'
  where child_user_id = p_child_user_id
    and status = 'active';

  update public.pairing_requests
  set status = 'cancelled', responded_at = now()
  where child_user_id = p_child_user_id
    and status = 'pending_child';

  perform private.record_audit(
    p_family_id,
    p_actor_user_id,
    null,
    'member_removed',
    'family_member',
    v_membership.id::text,
    jsonb_build_object('child_user_id', p_child_user_id)
  );

  return jsonb_build_object(
    'status', 'unlinked',
    'family_id', p_family_id,
    'child_user_id', p_child_user_id,
    'already_removed', false,
    'devices_revoked', v_devices,
    'sessions_ended', v_sessions
  );
end;
